mapper.select:
SELECT A.A1 AS REORGID, A.A1_NAME AS REORGNAME, A.A2 AS ORGID, A.A2_NAME AS ORGNAME, A.A3 AS SECOND_ORGID, A.A3_NAME AS SECOND_ORGNAME, C.TITLEID AS TITLEID, C.TITLENAME AS TITLENAME, C.EMPID , C.EMNAME, EMP.LOGIN AS EMPSNAME, EMP.STAT AS EMPSTAT, C.STAT AS ORMEMBERSTAT FROM (SELECT A.REORGID AS A1, A.REORGNAME A1_NAME, A.ORGID A2, A.ORGNAME AS A2_NAME, B.ORGID A3, B.ORGNAME A3_NAME FROM T_ECC_ORRELA A, T_ECC_ORRELA B WHERE A.ORGID = B.REORGID AND A.STAT='STAR' AND B.STAT='STAR') A, T_ECC_ORMEMBER C,T_ECC_EMPLOYEE EMP
WHERE C.ORGID = A.A3 AND EMP.EMPID=C.EMPID
AND C.EMPID=#{empID}
AND ( C.EMNAME LIKE CONCAT(CONCAT('%', #{empName}), '%') OR C.EMNAME LIKE CONCAT(CONCAT('%', #{empName}), '%') OR A.A2_NAME LIKE CONCAT(CONCAT('%', #{empName}), '%') OR A.A3_NAME LIKE CONCAT(CONCAT('%', #{empName}), '%') OR C.TITLENAME LIKE CONCAT(CONCAT('%', #{empName}), '%') )
AND EMP.LOGIN = #{empSName}
ORDER BY EMNAME ASC

 SELECT * FROM T_ECC_EMPLOYEE EMP 
 WHERE  1=1


		 	AND EMP.EMPID=#{empID}

	  SELECT EMP.EMPID ,EMP.EMNAME FROM   T_ECC_ORMEMBER C, T_ECC_EMPLOYEE EMP
			 WHERE  EMP.EMPID=C.EMPID AND EMP.STAT='STAR' AND C.STAT='STAR'
       AND C.ORGID=#{orgId} AND C.TITLEID=#{stationId}

SELECT EMP.EMPID, EMP.EMNAME FROM T_ECC_EMPLOYEE EMP WHERE STAT ='STAR'
AND ROWNUM <= #{limit}
AND EMP.EMNAME like '%'||#{empName}||'%'
